const r = $json;
const p = $('Build payload').item.json;
const who = `${p.sender_name ? p.sender_name + ' ' : ''}<${p.sender_email}>`;
let text;
if (r.is_duplicate) {
  text = `:repeat: Duplicate skipped — ${who} — "${p.subject}"`;
} else if (r.classification === 'JUNK') {
  text = `:wastebasket: JUNK — ${who} — "${p.subject}"`;
} else {
  const e = r.extraction || {};
  const rep = r.reply || {};
  const fmt = v => (v === null || v === undefined || v === '') ? '—'
    : (Array.isArray(v) ? (v.length ? v.join(', ') : 'none') : String(v));
  const money = (a, b) => (a == null && b == null) ? '—' : `${a != null ? '$' + a : '?'} – ${b != null ? '$' + b : '?'}`;
  const needs = r.status === 'Manual Review' ? ('YES' + (r.error ? ' — ' + r.error : '')) : 'no';
  const reply = rep.should_send ? 'SEND → awaiting approval in Slack' : `skip (${rep.skip_reason || '—'})`;
  const lines = [
    `:mag: *${r.classification}*${r.tier ? ' · ' + r.tier : ''} · ${r.status} — ${who} — "${p.subject}"`,
    `• Location: ${fmt(e.location)} | Bedrooms: ${fmt(e.bedrooms)} | Budget: ${money(e.budget_min, e.budget_max)}`,
    `• Move-in: ${fmt(e.move_in_date)} | Pets: ${fmt(e.pets)} | Occupants: ${fmt(e.occupants)} | Duration: ${fmt(e.duration_months)} mo`,
    `• Confidence: ${fmt(e.confidence)} | Missing: ${fmt(e.missing_fields)}`,
    e.notes ? `• Notes: ${e.notes}` : null,
    r.is_upgrade ? '• Upgrade from Tier 3' : null,
    `• Needs attention: ${needs}`,
    `• Reply decision: ${reply}`,
  ].filter(Boolean);
  text = lines.join('\n');
}
return [{ json: { text } }];

const r = $('POST /ingest').item.json;
const p = $('Build payload').item.json;

const strip = (h) =>
  (h || '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr|h\d|li|table)>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#x27;|&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

const quote = (s) =>
  String(s || '')
    .split('\n')
    .map((l) => '> ' + l)
    .join('\n');

const money = (n) => {
  if (n == null || n === '') return null;
  const num = Number(n);
  if (!Number.isFinite(num)) return null;
  return '$' + num.toLocaleString('en-US', { maximumFractionDigits: 0 });
};

const fmtBudget = (min, max) => {
  const a = money(min);
  const b = money(max);
  if (a && b) return `${a} – ${b}/mo`;
  if (b) return `up to ${b}/mo`;
  if (a) return `from ${a}/mo`;
  return null;
};

const fmtPets = (pets) => {
  if (pets == null) return null;
  if (Array.isArray(pets)) {
    if (pets.length === 0) return 'None';
    return pets.join(', ');
  }
  return String(pets);
};

/** Always "Key: Value" with a space after the colon. Skip blanks. */
const line = (key, value) => {
  if (value == null) return null;
  const v = String(value).trim();
  if (!v) return null;
  return `${key}: ${v}`;
};

const lines = (pairs) =>
  pairs.map(([k, v]) => line(k, v)).filter(Boolean).join('\n');

const x = r.extraction || {};
const m = r.match || {};
const reply = r.reply || {};

const inbound =
  p.body_plain && p.body_plain.trim()
    ? p.body_plain.trim()
    : strip(p.body_html);
const replyText = strip(reply.html);

const matchDetail = m.ready
  ? `YES (zip ${(m.request && m.request.zip_code) || x.zip_code || '?'}, ${(m.request && m.request.bedrooms) || x.bedrooms || '?'}BR, move-in ${(m.request && m.request.move_in_date) || x.move_in_date || '?'})`
  : `no (missing: ${(m.missing_fields || []).join(', ') || 'unknown'})`;

const header = lines([
  ['Action', 'Reply approval needed'],
  ['Tier', r.tier],
  ['Sender', `${p.sender_name || ''} <${p.sender_email}>`.trim()],
  ['Subject', p.subject],
  ['Status', r.status],
  ['Match Ready', m.ready ? 'yes' : 'no'],
]);

const extracted = lines([
  ['Location', x.location],
  ['Zip Code', x.zip_code],
  ['Bedrooms', x.bedrooms != null ? x.bedrooms : null],
  ['Bathrooms', x.bathrooms != null ? x.bathrooms : null],
  ['Budget', fmtBudget(x.budget_min, x.budget_max)],
  ['Move-in Date', x.move_in_date],
  ['Pets', fmtPets(x.pets)],
  ['Occupants', x.occupants != null ? x.occupants : null],
  ['Adults', x.adults != null ? x.adults : null],
  ['Children', x.children != null ? x.children : null],
  ['Duration', x.duration_months != null ? `${x.duration_months} months` : null],
  ['Phone', x.phone],
  ['Requester', x.requester_type],
  ['Company', x.company_name],
  [
    'Amenities',
    Array.isArray(x.amenities) && x.amenities.length
      ? x.amenities.join(', ')
      : null,
  ],
  ['Special Requests', x.special_requests],
]);

const footer = lines([
  ['Reply Subject', reply.subject],
  ['Property Match on Approve', matchDetail],
]);

const text = [
  ':envelope_with_arrow: *Reply approval needed*',
  '',
  header,
  extracted ? `\n${extracted}` : '',
  '',
  '*Inbound email:*',
  quote(inbound.slice(0, 1500)),
  '',
  '*Proposed reply:*',
  quote(replyText.slice(0, 2000)),
  footer ? `\n${footer}` : '',
]
  .join('\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

return [{ json: { text } }];

